const a="tradeaura-v1",c=["/","/index.html"];self.addEventListener("install",e=>{e.waitUntil(caches.open(a).then(n=>n.addAll(c))),self.skipWaiting()});self.addEventListener("activate",e=>{e.waitUntil(caches.keys().then(n=>Promise.all(n.filter(t=>t!==a).map(t=>caches.delete(t))))),self.clients.claim()});self.addEventListener("fetch",e=>{if(e.request.method!=="GET")return;if(new URL(e.request.url).pathname.startsWith("/api/")){e.respondWith(fetch(e.request).catch(()=>new Response("offline",{status:503})));return}e.respondWith(caches.match(e.request).then(t=>{const i=fetch(e.request).then(s=>(s.ok&&caches.open(a).then(r=>r.put(e.request,s.clone())),s)).catch(()=>t);return t||i}))});
